// typed client: transport details live here and nowhere else
export const ordersApi = {
  async list(): Promise<OrderDto[]> {
    const res = await fetch("/api/orders")
    if (!res.ok) throw new ApiError(res.status)
    return res.json()
  }
}

// mapping: DTO in, domain out — validated once
export function toOrder(dto: OrderDto): Order {
  return { id: dto.id, totalCents: dto.total_cents, placedAt: new Date(dto.placed_at) }
}
